import { IsNotEmpty, IsString, IsUUID, MaxLength } from 'class-validator';
import { IsAccountPassword, IsSignature, IsUsername } from '../../../common/validation';
import { KeyMaterialDto } from '../../user/dto/key-material.dto';

export class SetupDto extends KeyMaterialDto {
  /** The key the server printed when it started without an owner. */
  @IsString()
  @IsNotEmpty()
  @MaxLength(256)
  setupKey: string;

  /** Generated by the client: the owner's key material is bound to it. */
  @IsUUID('4')
  id: string;

  @IsUsername()
  username: string;

  @IsAccountPassword()
  password: string;

  /** The owner's signature over their own keys: the root every other certificate hangs from. */
  @IsSignature()
  keyCert: string;
}
